/* eslint-disable array-element-newline */

'use strict';

// MODULES //

import dtypes from '@stdlib/ndarray-dtypes';
import gcunone from '@stdlib/blas-ext-base-ndarray-gcunone';
import dcunone from '@stdlib/blas-ext-base-ndarray-dcunone';
import scunone from '@stdlib/blas-ext-base-ndarray-scunone';
import factory from '@stdlib/ndarray-base-unary-strided1d-dispatch-factory';


// VARIABLES //

var idtypes = dtypes( 'all' );
var odtypes = dtypes( 'boolean_and_generic' );
var policies = {
	'output': 'boolean_and_generic',
	'casting': 'none'
};
var table = {
	'types': [
		'float64', 'bool', // input, output
		'float32', 'bool'  // input, output

		// FIXME: add specialized support for `ccunone` and `zcunone` once the corresponding packages are implemented
	],
	'fcns': [
		dcunone,
		scunone
	],
	'default': gcunone
};
var options = {
	'strictTraversalOrder': true
};


// MAIN //

/**
* Cumulatively tests whether every element along one or more ndarray dimensions is falsy.
*
* @name cunone
* @type {Function}
* @param {ndarray} x - input ndarray
* @param {Options} [options] - function options
* @param {IntegerArray} [options.dims] - list of dimensions over which to perform operation
* @param {*} [options.dtype] - output ndarray data type
* @throws {TypeError} first argument must be an ndarray-like object
* @throws {TypeError} options argument must be an object
* @throws {RangeError} dimension indices must not exceed input ndarray bounds
* @throws {RangeError} number of dimension indices must not exceed the number of input ndarray dimensions
* @throws {Error} must provide valid options
* @returns {ndarray} output ndarray
*
* @example
* import Float64Array from '@stdlib/array-float64';
* import ndarray from '@stdlib/ndarray-ctor';
*
* // Create a data buffer:
* var xbuf = new Float64Array( [ 0.0, 0.0, 0.0, 4.0, 0.0, 0.0 ] );
*
* // Define the shape of the input array:
* var sh = [ 3, 1, 2 ];
*
* // Define the array strides:
* var sx = [ 2, 2, 1 ];
*
* // Define the index offset:
* var ox = 0;
*
* // Create an input ndarray:
* var x = new ndarray( 'float64', xbuf, sh, sx, ox, 'row-major' );
*
* // Perform operation:
* var out = cunone( x );
* // returns <ndarray>[ [ [ true, true ] ], [ [ true, false ] ], [ [ false, false ] ] ]
*/
var cunone = factory( table, [ idtypes ], odtypes, policies, options );


// EXPORTS //

export default cunone;
